      (["On annonce.","On examine.","On entoure."],[("d'abord","médecin des urgences","Il annonce le décès en binôme et vérifie la compréhension."),("en même temps","infirmier","Il prend les constantes et la glycémie et observe les réactions."),("ensuite","Care Team ou urgences psychiatriques","Ils soutiennent le proche et organisent son entourage.")]),
